async function refreshSportyBet(){
  var eventsById=new Map(),feedError=null,newestFetch=null;
  try{
    for(var page=1;page<=5;page++){
      var d;
      try{
        d=await readJson('./api/sportybet-basketball?pageSize=100&timeline=168&pageNum='+page+'&tournamentId=sr%3Atournament%3A132');
        if(!d||d.ok!==true||!Array.isArray(d.events))throw Error(d&&d.error||'SportyBet basketball feed unavailable');
      }catch(pageError){
        feedError='SportyBet page '+page+': '+String(pageError&&pageError.message||pageError);
        if(!eventsById.size)throw Error(feedError);
        break;
      }
      if(d.fetched_at)newestFetch=d.fetched_at;
      var newIds=0;
      d.events.forEach(function(e){
        if(!e||typeof e!=='object')return;
        var id=String(e.event_id||e.id||'');
        if(!id)return;
        var current=eventsById.get(id);
        if(!current){
          current=Object.assign({},e,{markets:[]});
          eventsById.set(id,current);
          newIds++;
        }else{
          var oldFetch=Date.parse(current.fetched_at||''),newFetch=Date.parse(e.fetched_at||'');
          if(Number.isFinite(newFetch)&&(!Number.isFinite(oldFetch)||newFetch>=oldFetch)){
            Object.keys(e).forEach(function(k){if(k!=='markets')current[k]=e[k];});
          }
        }
        var marketMap=new Map((current.markets||[]).map(function(m){
          return [String(m.id||'')+'|'+String(m.specifier||''),m];
        }));
        (Array.isArray(e.markets)?e.markets:[]).forEach(function(m){
          if(m&&typeof m==='object')marketMap.set(String(m.id||'')+'|'+String(m.specifier||''),m);
        });
        current.markets=Array.from(marketMap.values());
      });
      // The proxy filters raw catalogue pages to NBA, so short/empty NBA pages
      // do not prove the underlying SportyBet catalogue has reached its end.
      if(d.catalogue_page_has_more!==true)break;
    }
    if(!eventsById.size)throw Error('SportyBet source returned zero upcoming basketball events');
    S.sportybet=Array.from(eventsById.values());
    S.sportybetFetchedAt=newestFetch||new Date().toISOString();
    S.sportybetError=feedError;
  }catch(e){
    S.sportybetError=String(e&&e.message||e);
    S.sportybet=[];
  }
}

